def backfill_receivable_history(apps, schema_editor):
    """Give existing customer balances a readable opening audit trail."""
    ReceivableLedger = apps.get_model("sales", "ReceivableLedger")
    ReceivableEntry = apps.get_model("sales", "ReceivableEntry")
    CustomerPayment = apps.get_model("sales", "CustomerPayment")
    db_alias = schema_editor.connection.alias
