        if amount_due <= zero:
            continue

        ReceivableEntry.objects.using(db_alias).create(
            receivable_id=ledger.pk,
            entry_date=invoice.invoice_date,
            entry_type="INVOICE",
            amount=amount_due,
            balance_after=amount_due,
            reference=invoice.invoice_no,
            notes="Opening receivable history created during upgrade.",
        )

        running_paid = zero
        for payment in CustomerPayment.objects.using(db_alias).filter(
            invoice_id=ledger.invoice_id
        ).order_by("payment_date", "payment_id"):
            payment_amount = payment.amount or zero
            if payment_amount <= zero:
                continue
            running_paid += payment_amount
            balance_after = max(amount_due - running_paid, zero)
            ReceivableEntry.objects.using(db_alias).create(
                receivable_id=ledger.pk,
                entry_date=payment.payment_date,
                entry_type="PAYMENT",
                amount=payment_amount,
                balance_after=balance_after,
                reference=payment.reference or f"PAY-{payment.payment_id}",
                notes="Historical payment imported during upgrade.",
                created_by_id=payment.received_by_id,
            )

        # Some older data has only the aggregate balance fields, with no
        # individual CustomerPayment rows. Preserve the known amount as one
        # clearly-labelled opening movement rather than silently hiding it.
        aggregate_paid = ledger.amount_paid or zero
        if aggregate_paid > running_paid:
            inferred_amount = aggregate_paid - running_paid
            ReceivableEntry.objects.using(db_alias).create(
                receivable_id=ledger.pk,
                entry_date=ledger.last_payment_date or invoice.invoice_date,
                entry_type="PAYMENT",
                amount=inferred_amount,
                balance_after=max(amount_due - aggregate_paid, zero),
                reference="OPENING-BALANCE",
                notes="Historical aggregate payment imported during upgrade.",
            )


